input.command:
claude agents --json 2>/dev/null | python3 -c "import json,sys;[print(r.get('id'),r.get('state') or r.get('status'),'pid',r.get('pid')) for r in json.load(sys.stdin) if r.get('id')=='a4c348e5']"; S=/tmp/claude-1000/-home-agentops-dev-md-manager-ultra/9ef1cac0-1832-43a8-bc1f-712f36914ef4/scratchpad; ls $S/smoke-run | grep review; T=$(ls -t ~/.claude/projects/*smoke-run-review-worktree*/a4c348e5*.jsonl 2>/dev/null | head -1); echo "transcript: $T"; [ -n "$T" ] && python3 - "$T" <<'EOF'
import json, sys
tools = []
for line in open(sys.argv[1]):
    try: item = json.loads(line)
    except ValueError: continue
    msg = item.get('message') or {}
    for block in (msg.get('content') or []) if isinstance(msg.get('content'), list) else []:
        if block.get('type') == 'tool_use':
            tools.append((block.get('name'), str(block.get('input', {}).get('file_path') or block.get('input', {}).get('pattern') or '')[:80]))
print(len(tools), 'tool calls so far; last 8:')
for t in tools[-8:]: print(' ', t)
