76	  workflows: (projectId: string) => `/api/projects/${encodeSegments(projectId)}/workflows`,
77	  runs: (projectId: string, workflowId: string, options: { limit?: number; cursor?: string | null } = {}) => {
78	    const query = new URLSearchParams()
79	    if (options.limit !== undefined) query.set('limit', String(options.limit))
80	    if (options.cursor) query.set('cursor', options.cursor)
81	    const suffix = query.size ? `?${query}` : ''
82	    return `/api/projects/${encodeSegments(projectId)}/workflows/${encodeSegments(workflowId)}/runs${suffix}`
83	  },
84	  run: (scope: RunScope) => `/api/projects/${encodeSegments(scope.projectId)}/workflows/${encodeSegments(scope.workflowId)}/runs/${encodeSegments(scope.runId)}`,
85	  events: (scope: RunScope, after = 0) => `${paths.run(scope)}/events?after=${after}`,
86	  result: (scope: RunScope, nodeId: string, attempt: number) => `${paths.run(scope)}/results/${encodeSegments(nodeId)}/${attempt}`,
87	  artifact: (scope: RunScope, artifactId: string) => `${paths.run(scope)}/artifacts/${encodeSegments(artifactId)}`,
88	  review: (scope: RunScope, attempt: number) => `${paths.run(scope)}/reviews/${attempt}`,
89	  inputs: (scope: RunScope) => `${paths.run(scope)}/inputs`,
90	}
91	
92	async function request(path: string, signal: AbortSignal | undefined, accept: string): Promise<Response> {
93	  let response: Response
94	  try {
95	    response = await fetch(path, { signal, headers: { Accept: accept } })
96	  } catch (error) {
97	    if (signal?.aborted) throw error
98	    throw new ProjectsApiError('network', error instanceof Error ? error.message : 'Network failure', path)
99	  }
100	  if (!response.ok) {
101	    let body: unknown = null
102	    try { body = await response.json() } catch { /* not JSON */ }
103	    const parsed = errorBodySchema.safeParse(body)
104	    const message = parsed.success ? parsed.data.error.message : `The API responded with status ${response.status}.`
105	    throw new ProjectsApiError('http', message, path, { status: response.status, code: parsed.success ? parsed.data.error.code : null })
106	  }
107	  return response
108	}
109	
110	async function requestJson<T>(path: string, validate: (input: unknown) => T, signal?: AbortSignal): Promise<T> {
111	  const response = await request(path, signal, 'application/json')
112	  let body: unknown
113	  try {
114	    body = await response.json()
115	  } catch {
116	    throw new ProjectsApiError('malformed', 'the response body is not JSON.', path)
117	  }
118	  try {
119	    return validate(body)
120	  } catch (error) {
121	    throw new ProjectsApiError('malformed', error instanceof z.ZodError ? z.prettifyError(error) : error instanceof Error ? error.message : 'invalid payload', path)
122	  }
123	}
